mapper.select:
SELECT billRefundRecordId, refundDate, orderDate, billDate, orgId, billId, billNum, patientId, patientName, gender, mobile, treatmentRecordId, regDentistId, regDentistName, actualAmount, receivedAmount, refundAmount, refundOperatorId, refundOperatorName, refundReason FROM ( SELECT br.refund_id AS billRefundRecordId, DATE_FORMAT(br.refund_date, '%Y-%m-%d') AS refundDate, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, br.org_id AS orgId, br.bill_id AS billId, bb.bill_num AS billNum, br.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.gender AS gender, bp.mobile AS mobile, br.treatment_id AS treatmentRecordId, btp.registered_dentist_id AS regDentistId, btp.regDentistName AS regDentistName, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, br.refund_amount AS refundAmount, br.refund_operator_id AS refundOperatorId, be.employee_name AS refundOperatorName, br.refund_reason AS refundReason FROM base_refund br LEFT JOIN base_patient bp ON br.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) btp ON br.treatment_id = btp.treatment_id LEFT JOIN base_bill bb ON br.bill_id = bb.bill_id LEFT JOIN base_employee be ON br.refund_operator_id = be.user_id ) br
and br.orgId = #{query.orgId}
and concat(IFNULL(br.patientName, ''), IFNULL(br.pinyinName, ''), IFNULL(br.mobile, '')) like concat('%', #{query.keyWord}, '%')
and br.billNum like concat('%', #{query.billNum}, '%')
and br.refundDate >= #{query.refundStartDate}
and br.refundDate <= #{query.refundEndDate}
and br.billDate >= #{query.billStartDate}
and br.billDate <= #{query.billEndDate}
and br.regDentistId in
#{item}
order by br.billRefundRecordId desc

SELECT refundId, billNum, DATE_FORMAT(orderDate, '%Y-%m-%d') as orderDate, DATE_FORMAT(billDate, '%Y-%m-%d') as billDate, DATE_FORMAT(refundDate, '%Y-%m-%d') as refundDate, patientId, patientName, mobile, refundWorkload, employeeId FROM ( SELECT brd.refund_id as refundId, brd.bill_num as billNum, brd.order_date as orderDate, brd.bill_date as billDate, brd.refund_date as refundDate, brd.patient_id as patientId, brd.`name` as patientName, brd.pinyin_name as pinyinName, brd.mobile, SUM(brd.refund_amount) as refundWorkload, brd.executor_id as employeeId FROM ( SELECT brp.org_id, brp.patient_id, brp.`name`, brp.pinyin_name, brp.refund_date, brp.mobile, brd.bill_detail_id, brd.refund_id, brd.refund_amount, bbd.order_date, bbd.bill_date, bbd.bill_num, bbd.executor_id FROM base_refund_detail brd LEFT JOIN ( SELECT bbd.bill_detail_id, bbd.executor_id, bb.order_date, bb.bill_date, bb.bill_num FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id WHERE executor_id IS NOT NULL ) bbd ON brd.bill_detail_id = bbd.bill_detail_id LEFT JOIN ( SELECT br.org_id, br.refund_id, br.refund_date, br.patient_id, bp.pinyin_name, bp.`name`, bp.mobile FROM base_refund br LEFT JOIN base_patient bp ON br.patient_id = bp.patient_id ) brp ON brd.refund_id = brp.refund_id ) brd
and brd.org_id = #{query.orgId}
and DATE_FORMAT( brd.order_date, '%Y-%m' ) = #{query.queryDate}
and DATE_FORMAT( brd.order_date, '%Y' ) = #{query.queryDate}
and brd.executor_id = #{query.employeeId}
GROUP BY brd.refund_id ) rfd
and concat(IFNULL(rfd.patientName, ''), IFNULL(rfd.pinyinName, ''), IFNULL(rfd.mobile, '')) Like concat('%', #{query.keyword}, '%')
and rfd.billNum like concat('%', #{query.billNum} ,'%')
and DATE_FORMAT(rfd.orderDate, '%Y-%m-%d') = #{query.orderDate}
ORDER BY rfd.refundDate DESC

SELECT brd.bill_detail_id AS orderDetailId, brd.item_type AS itemType, brd.item_id AS itemId, bti.item_num AS itemNum, bti.item_name AS itemName, brd.refund_amount AS refundWorkload FROM ( SELECT brd.bill_detail_id, brd.refund_amount, brd.refund_id, bbd.item_id, bbd.item_type, bbd.executor_id FROM base_refund_detail brd LEFT JOIN base_bill_detail bbd ON brd.bill_detail_id = bbd.bill_detail_id ) brd LEFT JOIN base_tariff_info bti ON brd.item_type = bti.item_type AND brd.item_id = bti.item_id
and brd.refund_id = #{query.refundId}
and brd.executor_id = #{query.employeeId}

SELECT refundId, refundDate, billNum, patientId, patientName, mobile, matchingDentistId, matchingDentistName, refundAmount FROM ( SELECT bf.refund_id as refundId, DATE_FORMAT(bf.refund_date, '%Y-%m-%d') as refundDate, bf.bill_num as billNum, bf.patient_id as patientId, bf.`name` as patientName, bf.pinyin_name as pinyinName, bf.mobile, bf.registered_dentist_id as matchingDentistId, bf.employee_name as matchingDentistName, bf.refund_amount as refundAmount FROM ( SELECT br.org_id, br.refund_id, br.refund_date, br.refund_amount, bp.patient_id, bp.`name`, bp.pinyin_name, bp.mobile, bb.bill_num, bb.order_date, btp.treat_start_time, btp.registered_dentist_id, btp.employee_name, btp.assistant_1, btp.assistant_2, btp.assistant_3 FROM base_refund br LEFT JOIN base_bill bb ON br.treatment_id = bb.treatment_id LEFT JOIN ( SELECT btp.treatment_id, btp.treat_start_time, btp.registered_dentist_id, be.employee_name, btp.assistant_1, btp.assistant_2, btp.assistant_3 FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id GROUP BY btp.treatment_id ) btp ON br.treatment_id = btp.treatment_id LEFT JOIN base_patient bp ON br.patient_id = bp.patient_id ) bf
AND bf.org_id = #{query.orgId}
AND DATE_FORMAT( bf.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bf.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bf.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bf.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bf.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bf.treat_start_time, '%Y' ) <= #{query.endDate}
AND bf.assistant_1 = #{query.assistantId}
AND bf.assistant_2 = #{query.assistantId}
AND bf.assistant_3 = #{query.assistantId}
GROUP BY bf.refund_id ) bfr
and concat(IFNULL(bfr.patientName, ''), IFNULL(bfr.pinyinName, ''), IFNULL(bfr.mobile, '')) like concat('%', #{query.keyword}, '%')
and concat(bfr.`billNum`) like concat('%', #{query.billNum}, '%')
and bfr.refundDate >= #{query.refundStartDate}
and bfr.refundDate <= #{query.refundEndDate}

SELECT refundId, refundDate, billId, billNum, billDate, patientId, patientName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, refundAmount, refundOperatorId, refundOperatorName FROM ( SELECT br.refund_id AS refundId, DATE_FORMAT( br.refund_date, '%Y-%m-%d' ) AS refundDate, br.bill_id AS billId, bb.bill_num AS billNum, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, br.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name AS pinyinName, btp.regDentistId, btp.regDentistName, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS totalReceivedAmount, br.refund_amount AS refundAmount, br.refund_operator_id AS refundOperatorId, be.employee_name AS refundOperatorName FROM base_refund br LEFT JOIN base_bill bb ON br.bill_id = bb.bill_id LEFT JOIN base_patient bp ON br.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.treatment_id, btp.registered_dentist_id, be.employee_name ) btp ON br.treatment_id = btp.treatment_id LEFT JOIN base_employee be ON br.refund_operator_id = be.user_id
AND br.org_id = #{query.orgId}
AND DATE_FORMAT( br.refund_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT( br.refund_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT( br.refund_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT( br.refund_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT( br.refund_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT( br.refund_date, '%Y') <= #{query.endDate}
AND br.bill_id IN ( SELECT bill_id FROM base_bill bb
AND bb.bill_num IS NOT NULL AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y') <= #{query.endDate}
)
) br
AND concat(IFNULL(br.patientName, ''), IFNULL(br.pinyinName, ''), IFNULL(br.patientMobile, '')) like concat('%', #{query.patientKeyword}, '%')
AND concat(br.`billNum`) like concat('%', #{query.billNum}, '%')
AND br.refundDate >= #{query.refundStartDate}
AND br.refundDate >= #{query.refundEndDate}

SELECT refundId, refundDate, billId, billNum, billDate, patientId, patientName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, refundAmount, refundOperatorId, refundOperatorName FROM ( SELECT br.refund_id AS refundId, DATE_FORMAT( br.refund_date, '%Y-%m-%d' ) AS refundDate, br.bill_id AS billId, bb.bill_num AS billNum, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, br.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name AS pinyinName, btp.regDentistId, btp.regDentistName, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS totalReceivedAmount, br.refund_amount AS refundAmount, br.refund_operator_id AS refundOperatorId, be.employee_name AS refundOperatorName FROM base_refund br LEFT JOIN base_bill bb ON br.bill_id = bb.bill_id LEFT JOIN base_patient bp ON br.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.treatment_id, btp.registered_dentist_id, be.employee_name ) btp ON br.treatment_id = btp.treatment_id LEFT JOIN base_employee be ON br.refund_operator_id = be.user_id
AND br.org_id = #{query.orgId}
AND DATE_FORMAT( br.refund_date, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT( br.refund_date, '%Y-%m-%d') <= #{query.endDate}
AND DATE_FORMAT( br.refund_date, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT( br.refund_date, '%Y-%m') <= #{query.endDate}
AND DATE_FORMAT( br.refund_date, '%Y') >= #{query.startDate}
AND DATE_FORMAT( br.refund_date, '%Y') <= #{query.endDate}
AND br.bill_id IN ( SELECT bill_id FROM base_bill bb
AND bb.bill_num IS NOT NULL AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d') < #{query.startDate}
OR DATE_FORMAT( bb.bill_date, '%Y-%m-%d') > #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m') < #{query.startDate}
OR DATE_FORMAT( bb.bill_date, '%Y-%m') > #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y') < #{query.startDate}
OR DATE_FORMAT( bb.bill_date, '%Y') > #{query.endDate}
)
) br
AND concat(IFNULL(br.patientName, ''), IFNULL(br.pinyinName, ''), IFNULL(br.patientMobile, '')) like concat('%', #{query.patientKeyword}, '%')
AND concat(br.`billNum`) like concat('%', #{query.billNum}, '%')
AND br.refundDate >= #{query.refundStartDate}
AND br.refundDate >= #{query.refundEndDate}

